package com.eidolon.sc.mobile;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.time.*;import java.util.*;
/** Explicit allowlist of portable role settings. No credentials or device notification permissions. */
final class RuntimeSettings {
 static void create(SQLiteDatabase db,Context c){
  db.execSQL("CREATE TABLE role_runtime(character TEXT PRIMARY KEY,body TEXT NOT NULL)");
  // Runs inside SQLiteOpenHelper's migration transaction; legacy preferences are never read again.
  Map<String,JSONObject> rows=new HashMap<>();for(Map.Entry<String,?> e:c.getSharedPreferences("settings",0).getAll().entrySet()){
   String k=e.getKey(),field=k.startsWith("roleZone/")?"zone":k.startsWith("temporalOverride/")?"override":k.startsWith("temporalEvents/")?"events":"";if(field.isEmpty()||!(e.getValue() instanceof String))continue;String who=k.substring(k.indexOf('/')+1);if(who.isEmpty()||who.length()>100)continue;
   try{JSONObject row=rows.get(who);if(row==null){row=new JSONObject().put("character",who).put("zone","").put("events",new JSONArray());rows.put(who,row);}String raw=(String)e.getValue();if(field.equals("zone")){if(!raw.isEmpty())ZoneId.of(raw);row.put(field,raw);}else if(!raw.isEmpty())row.put(field,field.equals("events")?new JSONArray(raw):new JSONObject(raw));}catch(Exception bad){android.util.Log.w("EidolonTime","Skipped invalid legacy setting");}
  }
  for(JSONObject row:rows.values())try{validateRow(row);put(db,row);}catch(Exception bad){android.util.Log.w("EidolonTime","Skipped invalid legacy role state");}
 }
 static JSONObject read(ChatStore s,String who)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM role_runtime WHERE character=?",new String[]{who})){return c.moveToFirst()?new JSONObject(c.getString(0)):new JSONObject().put("character",who).put("zone","").put("events",new JSONArray());}}
 static JSONObject read(Context c,String who)throws Exception{try(ChatStore s=new ChatStore(c)){return read(s,who);}}
 static void put(SQLiteDatabase db,JSONObject row)throws Exception{validateRow(row);ContentValues v=new ContentValues();v.put("character",row.getString("character"));v.put("body",row.toString());db.insertWithOnConflict("role_runtime",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 static void zone(Context c,String who,String zone)throws Exception{if(!zone.isEmpty())ZoneId.of(zone);try(ChatStore s=new ChatStore(c)){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{JSONObject row=read(s,who).put("zone",zone);put(db,row);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 static JSONObject override(Context c,String who,JSONObject value,long now)throws Exception{try(ChatStore s=new ChatStore(c)){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{JSONObject row=read(s,who);if(value==null)row.remove("override");else{row.put("override",value);JSONArray a=row.getJSONArray("events");while(a.length()>=20)a.remove(0);a.put(new JSONObject().put("at",now).put("name",value.getString("name")).put("status","user_reported_start").put("source","explicit_user_override"));}put(db,row);db.setTransactionSuccessful();return value==null?new JSONObject():value;}finally{db.endTransaction();}}}
 static JSONArray all(ChatStore s)throws Exception{JSONArray a=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM role_runtime ORDER BY character",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 static void validateRow(JSONObject r)throws Exception{
  if(r.toString().length()>16000||r.getString("character").isEmpty()||r.getString("character").length()>100)throw new Exception("角色时间设置无效");for(Iterator<String> it=r.keys();it.hasNext();)if(!Arrays.asList("character","zone","override","events").contains(it.next()))throw new Exception("角色时间设置含未知字段");String z=r.getString("zone");if(!z.isEmpty())ZoneId.of(z);
  JSONObject o=r.optJSONObject("override");if(r.has("override")&&o==null)throw new Exception("临时状态格式无效");if(o!=null){LifeData.shortText(o.getString("name"),80);long from=o.getLong("from"),until=o.getLong("until");if(from<0||until<=from||until-from>86400000L||until>253402300799999L||!o.getBoolean("confirmed")||!o.getString("source").equals("explicit_user_override")||!o.getString("state").equals("user_defined_activity"))throw new Exception("临时状态时间或来源无效");for(String key:new String[]{"availability","interruptibility"})if(!Arrays.asList("high","low","unknown").contains(o.getString(key)))throw new Exception("临时状态行为无效");if(!Arrays.asList("normal","brief_attentive").contains(o.getString("response_style")))throw new Exception("临时回复行为无效");for(Iterator<String> it=o.keys();it.hasNext();)if(!Arrays.asList("name","state","from","until","confirmed","source","availability","interruptibility","response_style").contains(it.next()))throw new Exception("临时状态含未知字段");}
  JSONArray a=r.getJSONArray("events");if(a.length()>20)throw new Exception("临时事件过多");for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);LifeData.shortText(e.getString("name"),80);if(e.getLong("at")<0||e.getLong("at")>253402300799999L||!e.getString("source").equals("explicit_user_override")||!e.getString("status").equals("user_reported_start")||e.length()!=4)throw new Exception("临时事件格式无效");}
 }
 static void validateBackup(JSONObject data,Set<String> known)throws Exception{JSONArray a=data.getJSONArray("runtimeSettings");if(a.length()>known.size())throw new Exception("角色时间设置过多");Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);validateRow(r);if(!known.contains(r.getString("character"))||!seen.add(r.getString("character")))throw new Exception("角色时间设置重复或未知角色");}}
 static void clearObservationCache(Context c){SharedPreferences p=c.getSharedPreferences("settings",0);SharedPreferences.Editor e=p.edit();for(String k:p.getAll().keySet())if(k.startsWith("temporal/"))e.remove(k);e.apply();}
 static void restore(ChatStore s,JSONObject data)throws Exception{SQLiteDatabase db=s.getWritableDatabase();db.delete("role_runtime",null,null);if(data.optInt("version")>=15){JSONArray a=data.getJSONArray("runtimeSettings");for(int i=0;i<a.length();i++)put(db,a.getJSONObject(i));}}
 private RuntimeSettings(){}
}
